key_counts=Counter();pair_counts=Counter();active_core=0;active_pair=0;active_own=0;strict_counts=Counter();regions=defaultdict(lambda:{'handStates':0,'events':Counter(),'firstTime':None,'lastTime':None,'worstCore':None,'worstPair':None,'supports':set()})
