triage={'significantQueueEntries':sum(not a['kind'].startswith('strictExisting') for a in q),'strictOnlyQueueEntries':sum(a['kind'].startswith('strictExisting') for a in q),'newCoreKeys':dict(key_counts),'newNeighborPairs':dict(pair_counts),'strictExistingPairs':dict(strict_counts),'newCoreKeyStatesOnActiveDigits':active_core,'newNeighborPairStatesInvolvingActiveDigits':active_pair,'newOwnPalmStatesInvolvingActiveDigits':active_own,'significantRegions':[{**v,'events':dict(v['events']),'supports':[{'id':i,'hand':'R' if rec[i]['hi'] else 'L','finger':rec[i]['fi']+1,'previous':rec[i].get('previous'),'next':rec[i].get('next'),'begin':rec[i]['begin'],'end':rec[i]['end']} for i in sorted(v['supports'])]} for v in sorted(regions.values(),key=lambda v:v['firstTime'])]}
